import spidev,time,json
for extras in [[],['bits_per_word'],['lsbfirst'],['cshigh'],['bits_per_word','lsbfirst','cshigh'],[]]:
 a=spidev.SpiDev();g=spidev.SpiDev();a.open(0,0);g.open(0,1)
 try:
  for d in (a,g):
   d.mode=3;d.max_speed_hz=1000000
   for key in extras:setattr(d,key,8 if key=='bits_per_word' else False)
  a.xfer2([128,0,0]);time.sleep(.01)
  pairs=[]
  for i in range(4):
   pairs.append([list(a.xfer2([128,0,0])),list(g.xfer2([128,0]))]);time.sleep(.01)
  print(extras,'properties',[(d.mode,d.bits_per_word,d.lsbfirst,d.cshigh) for d in (a,g)],pairs)
 finally:a.close();g.close()
